const transaction = (context.get('transaction') || 0) + 1;
context.set('transaction', transaction & 0xffff);
const mbap = Buffer.from([(transaction >> 8) & 0xff, transaction & 0xff, 0, 0, 0, 6, 1]);
msg.payload = Buffer.concat([mbap, Buffer.from([3, 0, 0, 0, 1])]);
return msg;

const frame = Buffer.from(msg.payload || []);
if (frame.length < 11) { node.error('Resposta Modbus incompleta para teste_1'); return null; }
if ((frame[7] & 0x80) !== 0) { node.error(`Exceção Modbus teste_1: ${frame[8]}`); return null; }
msg.payload = { equipment_code: 'teste_1', clp: 'modbus-virtual:1502', register: 'holding[0]', loaded_quantity: frame.readUInt16BE(9), communication: 'ONLINE', read_only: true };
return msg;

